use crate::aap::caps::state_read;

/// Hosts this run is permitted to reach. Every URL this node emits must have a
/// host in this list, because the downstream fetch is refused for any other host.
const ALLOWED_HOSTS: &[&str] = &[
    "bytecodealliance.org",
    "lobste.rs",
    "rss.arxiv.org",
    "simonwillison.net",
];

/// Fallback subscriptions, used when the `subscriptions` store yields no usable
/// URL. Every entry is on an allowed host, so the fallback can never reach
/// outside the allowlist.
const FALLBACK_URLS: &[&str] = &[
    "https://simonwillison.net/atom/everything/",
    "https://lobste.rs/rss",
    "https://rss.arxiv.org/rss/cs.AI",
    "https://bytecodealliance.org/feed.xml",
];

struct Node;

/// Return the host of an http(s) URL, or None if the URL has no usable host.
/// URLs carrying userinfo (`user@host`) are rejected, since they make the
/// host ambiguous.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(|c: char| c == '/' || c == '?' || c == '#').next()?;
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

/// True only if the URL's host exactly matches an allowlisted host.
fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| h.eq_ignore_ascii_case(a)),
        None => false,
    }
}

/// Split a stored value into URLs. Accepts newline, carriage-return, comma,
/// semicolon, and whitespace separators, strips surrounding quotes, keeps only
/// http(s) URLs on allowlisted hosts, and removes duplicates while preserving order.
fn parse_urls(raw: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for token in raw.split(|c: char| matches!(c, '\n' | '\r' | ',' | ';') || c.is_whitespace()) {
        let t = token.trim().trim_matches(|c: char| c == '"' || c == '\'');
        if is_allowed(t) && !out.iter().any(|u| u == t) {
            out.push(t.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls: Vec<String> = state_read::get("urls")
            .map(|raw| parse_urls(&raw))
            .unwrap_or_default();

        let urls: Vec<String> = if urls.is_empty() {
            FALLBACK_URLS
                .iter()
                .filter(|u| is_allowed(u))
                .map(|s| s.to_string())
                .collect()
        } else {
            urls
        };

        SubscriptionList { urls }
    }
}

export!(Node);
